package br.edu.utfpr.cantina.service;
import br.edu.utfpr.cantina.model.Produto; import br.edu.utfpr.cantina.repository.ProdutoRepository; import java.sql.SQLException; import java.util.*;
public class ProdutoService { private final ProdutoRepository repo; public ProdutoService(ProdutoRepository r){repo=r;} public List<Produto> listar()throws SQLException{return repo.listar();} public void salvar(Produto p)throws SQLException{if(p.getNome()==null||p.getNome().trim().isEmpty())throw new IllegalArgumentException("Informe o nome do produto.");if(p.getNome().trim().length()>120)throw new IllegalArgumentException("Nome deve ter até 120 caracteres.");if(p.getPreco()==null||p.getPreco().signum()<0)throw new IllegalArgumentException("Informe um preço válido.");if(p.getQuantidadeEstoque()<0)throw new IllegalArgumentException("Estoque não pode ser negativo.");p.setNome(p.getNome().trim());repo.salvar(p);} public void excluir(int id)throws SQLException{if(id<=0)throw new IllegalArgumentException("Selecione um produto.");repo.excluir(id);} }
